from pathlib import Path

ROOT = Path('.')


def read(path):
    return (ROOT / path).read_text(encoding='utf-8')


def write(path, text):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'{label}: expected 1 occurrence, found {count}')
    return text.replace(old, new, 1)


# 1) FfFrameExtractor: expose decoded PTS occurrence identity.
path = 'Services/Video/FfFrameExtractor.cs'
text = read(path)
text = replace_once(
    text,
    '''        private double _lastDecodedTimestampSeconds = double.NaN;\n        private string _lastDecodedTimestampSource = "none";\n''',
    '''        private double _lastDecodedTimestampSeconds = double.NaN;\n        private string _lastDecodedTimestampSource = "none";\n        private long _lastDecodedPresentationTimestamp = ffmpeg.AV_NOPTS_VALUE;\n        private int _lastDecodedTimestampOccurrence;\n''',
    'extractor identity fields')
text = replace_once(
    text,
    '''            _lastDecodedTimestampSeconds = double.NaN;\n            _lastDecodedTimestampSource = "none";\n            _sequentialActive = true;\n''',
    '''            _lastDecodedTimestampSeconds = double.NaN;\n            _lastDecodedTimestampSource = "none";\n            _lastDecodedPresentationTimestamp = ffmpeg.AV_NOPTS_VALUE;\n            _lastDecodedTimestampOccurrence = 0;\n            _sequentialActive = true;\n''',
    'extractor identity reset')
old_capture = '''        private void CaptureDecodedTimestamp(int frameIndex, long pts)\n        {\n            double timeBaseSeconds = ffmpeg.av_q2d(_timeBase);\n            if (pts != ffmpeg.AV_NOPTS_VALUE &&\n                timeBaseSeconds > 0 &&\n                double.IsFinite(timeBaseSeconds))\n            {\n                // LastDecodedTimestampSeconds is consumed as a video-relative timeline\n                // value by playback and analysis. Keep PTS-backed samples on the same\n                // origin as TryGetCachedFrameTimestampSeconds instead of exposing raw\n                // stream PTS seconds and mixing them with zero-origin FPS fallbacks.\n                long originPts = GetFirstKnownPresentationTimestamp();\n                if (originPts != ffmpeg.AV_NOPTS_VALUE)\n                {\n                    double timestampSeconds =\n                        ((double)pts - originPts) * timeBaseSeconds;\n                    if (double.IsFinite(timestampSeconds))\n                    {\n                        _lastDecodedTimestampSeconds = Math.Max(0, timestampSeconds);\n                        _lastDecodedTimestampSource = "pts";\n                        return;\n                    }\n                }\n            }\n\n            // If the decoded timeline has no trustworthy first-frame PTS, there is no\n            // safe absolute-to-relative origin. Stay entirely on the deterministic\n            // ordinal/FPS fallback rather than switching origins mid-stream.\n            _lastDecodedTimestampSeconds = _fps > 0\n                ? frameIndex / _fps\n                : double.NaN;\n            _lastDecodedTimestampSource = double.IsFinite(_lastDecodedTimestampSeconds)\n                ? "fps-fallback"\n                : "none";\n        }\n'''
new_capture = '''        private void CaptureDecodedTimestamp(int frameIndex, long pts)\n        {\n            _lastDecodedPresentationTimestamp = pts;\n            _lastDecodedTimestampOccurrence = 0;\n            if (pts != ffmpeg.AV_NOPTS_VALUE)\n            {\n                lock (_decodedFrameTimeline.SyncRoot)\n                {\n                    if (frameIndex >= 0 &&\n                        frameIndex < _decodedFrameTimeline.Entries.Count)\n                    {\n                        DecodedFrameTimelineEntry entry =\n                            _decodedFrameTimeline.Entries[frameIndex];\n                        if (entry.PresentationTimestamp == pts)\n                            _lastDecodedTimestampOccurrence = entry.TimestampOccurrence;\n                    }\n                }\n            }\n\n            double timeBaseSeconds = ffmpeg.av_q2d(_timeBase);\n            if (pts != ffmpeg.AV_NOPTS_VALUE &&\n                timeBaseSeconds > 0 &&\n                double.IsFinite(timeBaseSeconds))\n            {\n                // LastDecodedTimestampSeconds is consumed as a video-relative timeline\n                // value by playback and analysis. Keep PTS-backed samples on the same\n                // origin as TryGetCachedFrameTimestampSeconds instead of exposing raw\n                // stream PTS seconds and mixing them with zero-origin FPS fallbacks.\n                long originPts = GetFirstKnownPresentationTimestamp();\n                if (originPts != ffmpeg.AV_NOPTS_VALUE)\n                {\n                    double timestampSeconds =\n                        ((double)pts - originPts) * timeBaseSeconds;\n                    if (double.IsFinite(timestampSeconds))\n                    {\n                        _lastDecodedTimestampSeconds = Math.Max(0, timestampSeconds);\n                        _lastDecodedTimestampSource = "pts";\n                        return;\n                    }\n                }\n            }\n\n            // If the decoded timeline has no trustworthy first-frame PTS, there is no\n            // safe absolute-to-relative origin. Stay entirely on the deterministic\n            // ordinal/FPS fallback rather than switching origins mid-stream.\n            _lastDecodedTimestampSeconds = _fps > 0\n                ? frameIndex / _fps\n                : double.NaN;\n            _lastDecodedTimestampSource = double.IsFinite(_lastDecodedTimestampSeconds)\n                ? "fps-fallback"\n                : "none";\n        }\n'''
text = replace_once(text, old_capture, new_capture, 'capture decoded identity')
insert_after = '''        public string LastDecodedTimestampSource\n        {\n            get\n            {\n                lock (_sync)\n                    return _lastDecodedTimestampSource;\n            }\n        }\n\n'''
identity_api = insert_after + '''        /// <summary>\n        /// Returns the raw decoded presentation identity for the most recent\n        /// sequential frame. The occurrence disambiguates repeated PTS values.\n        /// </summary>\n        public bool TryGetLastDecodedPresentationIdentity(\n            out long presentationTimestamp,\n            out int timestampOccurrence)\n        {\n            lock (_sync)\n            {\n                presentationTimestamp = _lastDecodedPresentationTimestamp;\n                timestampOccurrence = _lastDecodedTimestampOccurrence;\n                return presentationTimestamp != ffmpeg.AV_NOPTS_VALUE &&\n                    timestampOccurrence > 0;\n            }\n        }\n\n'''
text = replace_once(text, insert_after, identity_api, 'extractor identity API')
write(path, text)

# 2) Dedicated manual player and identity.
write('Services/Video/Session/ManualFramePlayer.cs', '''using Avalonia.Media.Imaging;\nusing System;\nusing System.Threading;\n\nnamespace FaceShield.Services.Video.Session;\n\ninternal readonly record struct ManualFrameIdentity(\n    int FrameOrdinal,\n    long? PresentationTimestamp,\n    int TimestampOccurrence,\n    double TimelineSeconds,\n    string TimelineSource)\n{\n    internal bool HasPresentationTimestamp =>\n        PresentationTimestamp.HasValue && TimestampOccurrence > 0;\n}\n\ninternal sealed class ManualPlayerFrame\n{\n    internal ManualPlayerFrame(\n        WriteableBitmap bitmap,\n        ManualFrameIdentity identity)\n    {\n        Bitmap = bitmap ?? throw new ArgumentNullException(nameof(bitmap));\n        Identity = identity;\n    }\n\n    internal WriteableBitmap Bitmap { get; }\n    internal ManualFrameIdentity Identity { get; }\n}\n\ninternal sealed class ManualFramePlayer : IDisposable\n{\n    private readonly FfFrameExtractor _extractor;\n    private readonly SemaphoreSlim _decodeGate = new(1, 1);\n    private bool _hasSequentialPosition;\n    private int _nextFrameIndex;\n    private int _disposed;\n\n    internal ManualFramePlayer(\n        string videoPath,\n        CancellationToken cancellationToken = default)\n    {\n        _extractor = new FfFrameExtractor(\n            videoPath,\n            enableHardware: true,\n            cancellationToken: cancellationToken);\n    }\n\n    internal bool ReachedEndOfStream => _extractor.SequentialReachedEndOfStream;\n    internal bool ReadCancelled => _extractor.SequentialReadCancelled;\n    internal string? DecodeError => _extractor.SequentialDecodeError;\n\n    internal ManualPlayerFrame? LoadFrame(\n        int frameIndex,\n        CancellationToken cancellationToken)\n    {\n        int requested = Math.Max(0, frameIndex);\n        _decodeGate.Wait(cancellationToken);\n        try\n        {\n            ThrowIfDisposed();\n\n            if (!_hasSequentialPosition || requested != _nextFrameIndex)\n            {\n                _extractor.StartSequentialRead(requested, cancellationToken);\n                _hasSequentialPosition = true;\n                _nextFrameIndex = requested;\n            }\n\n            return ReadNextLocked(cancellationToken);\n        }\n        catch (OperationCanceledException)\n        {\n            _hasSequentialPosition = false;\n            throw;\n        }\n        finally\n        {\n            _decodeGate.Release();\n        }\n    }\n\n    internal ManualPlayerFrame? ReadNext(\n        int fallbackStartFrameIndex,\n        CancellationToken cancellationToken)\n    {\n        _decodeGate.Wait(cancellationToken);\n        try\n        {\n            ThrowIfDisposed();\n\n            if (!_hasSequentialPosition)\n            {\n                int start = Math.Max(0, fallbackStartFrameIndex);\n                _extractor.StartSequentialRead(start, cancellationToken);\n                _hasSequentialPosition = true;\n                _nextFrameIndex = start;\n            }\n\n            return ReadNextLocked(cancellationToken);\n        }\n        catch (OperationCanceledException)\n        {\n            _hasSequentialPosition = false;\n            throw;\n        }\n        finally\n        {\n            _decodeGate.Release();\n        }\n    }\n\n    private ManualPlayerFrame? ReadNextLocked(\n        CancellationToken cancellationToken)\n    {\n        if (!_extractor.TryGetNextFrame(\n                cancellationToken,\n                out WriteableBitmap? bitmap,\n                out int frameIndex))\n        {\n            if (cancellationToken.IsCancellationRequested)\n            {\n                _hasSequentialPosition = false;\n                cancellationToken.ThrowIfCancellationRequested();\n            }\n\n            if (_extractor.SequentialReadCancelled)\n                _hasSequentialPosition = false;\n            return null;\n        }\n\n        if (bitmap == null)\n            return null;\n\n        long? presentationTimestamp = null;\n        int timestampOccurrence = 0;\n        if (_extractor.TryGetLastDecodedPresentationIdentity(\n                out long rawTimestamp,\n                out int occurrence))\n        {\n            presentationTimestamp = rawTimestamp;\n            timestampOccurrence = occurrence;\n        }\n\n        _nextFrameIndex = frameIndex == int.MaxValue\n            ? int.MaxValue\n            : frameIndex + 1;\n        _hasSequentialPosition = true;\n\n        return new ManualPlayerFrame(\n            bitmap,\n            new ManualFrameIdentity(\n                frameIndex,\n                presentationTimestamp,\n                timestampOccurrence,\n                _extractor.LastDecodedTimestampSeconds,\n                _extractor.LastDecodedTimestampSource));\n    }\n\n    private void ThrowIfDisposed()\n    {\n        if (Volatile.Read(ref _disposed) != 0)\n            throw new ObjectDisposedException(nameof(ManualFramePlayer));\n    }\n\n    public void Dispose()\n    {\n        if (Interlocked.Exchange(ref _disposed, 1) != 0)\n            return;\n\n        _extractor.Dispose();\n        _decodeGate.Dispose();\n    }\n}\n''')

