    '''        var session = _session;\n        if (_disposed || session == null)\n            return;\n        if (index < 0)\n            return;\n\n        if (_useManualPlayer)\n        {\n            await LoadManualFrameAsync(index);\n            return;\n        }\n\n        PersistCurrentMask();\n''',
